changeSet.sql:
CREATE TABLE nexus.index_failures (
    id           BIGSERIAL    NOT NULL,
    tenant_id    TEXT         NOT NULL,
    run_id       TEXT         NOT NULL DEFAULT '',
    file_path    TEXT         NOT NULL,
    error_class  TEXT         NOT NULL DEFAULT '',
    error        TEXT         NOT NULL DEFAULT '',
    occurred_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT index_failures_pk PRIMARY KEY (id)
);

-- BTree indexes: nx doctor / `nx index failures` list+count queries
CREATE INDEX idx_index_failures_ts  ON nexus.index_failures (tenant_id, occurred_at DESC);
CREATE INDEX idx_index_failures_run ON nexus.index_failures (tenant_id, run_id, occurred_at DESC);

ALTER TABLE nexus.index_failures ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.index_failures FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.index_failures
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON nexus.index_failures;
ALTER TABLE nexus.index_failures NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.index_failures DISABLE ROW LEVEL SECURITY;
